from collections import deque

def is_rbs(expression):
    balance = 0
    for char in expression:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def calculate_expression(expression):
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return None
            stack.pop()
    if len(stack) == 0:
        return expression
    else:
        return None

def max_rbs_rearrangement(sequences):
    n = len(sequences)
    brackets = [''] * (n << 1)
    for i in range(n):
        brackets[i << 1] = '('
        brackets[i << 1 | 1] = sequences[i]
    swaps = {}
    dp = [0] * (n + 1)

    for i in range(n):
        for j in range(i, n):
            if is_rbs(brackets[i << 1 : (j << 1) + 1]):
                dp[min(n, i * 2 + 1)] = max(dp[min(n, i * 2 + 1)], j - i + 1)
            k = (i << 1) + j
            if sequences[j] != '(':
                if dp[k - 1] != 0 and calculate_expression(brackets[(k - 1) // 2 : k // 2 + 2]) is not None:
                    for key in list(reversed(sorted(swaps))):
                        if key in dp:
                            dp[key] += dp[k - 1]
        swapped_length = len(sequences) - len(dp)
        if swapped_length == 1 and calculate_expression(brackets[i << 1 : (swapped_length << 1) + 1]) is not None:
            swaps[dp[-1]] = min(dp.index(swapped_length), swapped_length)
        for key in dp:
            if swapped_length not in dp or swapped_length < dp[key]:
                dp.append(swapped_length)

    return dp[-1]

