def rearrange_brackets(bracket_sequences, n):
    valid_sequences = [bracket_sequences[i] for i in range(n) if is_valid_bracket_sequence(bracket_sequences[i])]
    if not valid_sequences:
        return 0

    cached_results = [None] * n
    for i in range(n):
        current = bracket_sequences[i]
        length = len(current)
        for start in range(length):
            for end in range(start+1, length+1):
                suffix = current[start:end]
                if is_valid_bracket_sequence(suffix):
                    if (i, start, end) not in cached_results:
                        cached_results[(i, start, end)] = rearrange_brackets(valid_sequences, n) + 1
                    answer = cached_results[(i, start, end)]
                    if (i, start, end) not in cached_results:
