from collections import defaultdict

def compute_turns(n, edges, k, vertex):
    # Build adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Depth-first search function to find a maximum path that doesn't pass through vertex
    def dfs(node):
        max_path = 0
        for neighbor in adj_list[node]:
            if neighbor == vertex:
                max_path += 1
            elif dfs(neighbor):
                return neighbor
        return max_path + 1 if max_path == 0 else max_path

    def dfs_restricted(node):
        if node == vertex:
            return 1
        elif dfs(node):
            return dfs_restricted(dfs(node))
        return 0

    turns = k
    for i in range(k):
        if dfs_restricted(vertex) == 0:
            turns = k + 1 - i

    return turns

