def count_polynomials(t: int, a: int, b: int):
    MOD = 10**9 + 7

    # If a is exactly 1 and b equals to t, then there are infinite solutions
    if a == 1 and b == t:
        return "inf"

    # If only one coefficient can make P(t) = a, then check if all other coefficients can make P(P(t)) = b
    if len(set(a)) == 1:
        unique_coeff = set(a)
        if unique_coeff.issubset({1, 2, ..., t}):
            if unique_coeff.issuperset({2, 4, ..., t}):
                return "1"
            else:
                return "0"
        else:
            return str((b & (t-1)) != (t-1))

    # For other cases, the number of such polynomials is 0
