def valid_euler_tour(start_acorn, tour_sequence):
    tree = [set() for _ in range(len(tour_sequence))]
    for i, acorn in enumerate(tour_sequence):
        if acorn != 0:  # Exclude invalid zeros
            tree[acorn - 1].add(i)
            if start_acorn == acorn:  # Euler tour starts
                start_acorn = acorn

    # Check Euler tour properties
    total_acorns = 2 * len(tour_sequence) - 1
    visited = [False] * total_acorns
    for i in range(total_acorns):
        if len(tree[i]) and i == end_index(tree[i], tree):
            # Check for bidirectional simplicity relations
            left_redo = 0
            for j in tree[i]:
                left_redo |= visited[j]
            right_redo = 0
            for j in tree[i][::-1]:
                right_redo += visited[j]

            if (left_redo != 0 and right_redo != 0 and start_acorn != i) or \
               (left_redo == 0 and right_redo == 0 and start_acorn == i):
                return False

    return is_valid_end_index(tree, start_acorn)

def is_valid_end_index(tree, start_acorn):
    n = len(tree)
    for i in range(len(tree)):
        if any(tree[i]) and tree[i][::-1] == range(0, n, n - 1) and not any(end_index(i, tree) - start_acorn == n for start_acorn in range(n)):
            return True
    return False

