    initial_index = (-1 if tree_node[0] < target_index else len(tree_node) - 1 if tree_node[initial_index][0] > target_index else -1)
    while initial_index != target_index:
        temp = set()
        for idx in tree_node:
            if tree_node[idx] & tmp == target_index:
                continue
            else:
                tmp = tmp | tree_node[idx]
