from collections import deque

def build_tree(n, edges):
    tree = [[] for _ in range(n)]
    for u, v in edges:
        tree[u-1].append(v-1)
        tree[v-1].append(u-1)
    return tree

def find_all_paths(tree, start, end):
    visited = [False] * len(tree)
    paths = [{} for _ in range(len(tree))]
    paths[start][start] = 0

    queue = deque([(start, 1)])
    while queue:
        node, path_len = queue.popleft()
        for neighbor in tree[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                if neighbor == end:
                    paths[end] = {'paths': [path_len], 'visited': visited}
                else:
                    paths[neighbor] = paths[node].copy()
                    paths[neighbor][neighbor] = path_len + 1
                    paths[neighbor] |= {'paths': [path_len + 1]}
                    queue.append((neighbor, path_len + 1))
                    visited[neighbor] = False

    return paths.get(end, {})

def calculate_game_duration(final_paths, initial_loc):
    return len(final_paths['paths']) - final_paths['visited'].count(initial_loc)

