import sys

def is_cactus(u, is_root, parent, graph, visited, cycle_stack, max_beauty):
    visited[u] = True
    cycle_stack[u] = True
    cycle_begin = False

    for v in graph[u]:
        if v > 0 and v != parent and not visited[v]:
            v_out = False
            for t in range(is_root - 1, -1, -1):
                if graph[v][t] == u:
                    v_out = True
                    break
            if not v_out:
                continue
            if v_out and v < max_beauty:
                return False
            if not is_cactus(v, False, u, graph, visited, cycle_stack, max_beauty):
                return False
        else:
            if visited[v] and cycle_stack[v]:
                cycle_begin = True
            elif not cycle_stack[v]:
                cycle_stack[v] = True
                for t in parent: 
                    if graph[v][t] == u:
                        continue
                    cycle_stack[t] = True
                for t in parent:
                    if graph[v][t] == u and not graph[t][v]:
                        pass
    cycle_stack[u] = False
    return cycle_begin

def max_cactus_beauty(n, m, tree, additional_edges):
    graph = [[] for _ in range(n+1)]
    parent = [-1] * n
    visited = [False] * (n+1)
    cycle_stack = [False] * (n+1)

    for i in range(1, n):
        graph[tree[i-1]].append(tree[i])
        parent[i] = tree[i-1]

    max_edge_beauty = [-1] * m
    for edge in additional_edges:
        ui, vi, ci = edge
        if is_cactus(ui, False, -1, graph, visited, cycle_stack, ci):
            max_edge_beauty[edge[2] - 1] = ci

    max_beauty = -sys.maxsize
    for i in range(m):
        if max_edge_beauty[i] > max_beauty:
            max_beauty = max_edge_beauty[i]

    return max_beauty

# Example usage
n, m = [int(x) for x in input().split()]
tree = list(map(int, input().split()))
additional_edges = [list(map(int, input().split())) for _ in range(m)]

print(max(0, max_cactus_beauty(n, m, tree, additional_edges)))
