def solve(t, a, b):
    count = 0
    for k in range(a + 1):
        if pow(t, k, MOD) == b:
            count = (count + 1) % MOD
    for i in range(1, t):
        for j in range(i + 1):
            a1 = pow(t, i + j) % MOD
            for j1 in range(a1):
