def fast_mod_exp(x, n, m):
    result = 1
    base = x
    while n:
        if n & 1:
            result = (result * base) % m
        base = (base * base) % m
        n >>= 1
    return result

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, y, x = extended_gcd(b % a, a)
    y = y - (b // a) * x
    return gcd, x, y

def ncr(n, r):
