from collections import deque

from typing import List

def can_make_nice(n: int, k: int, heights: List[int]) -> bool:
    queue = deque([-1])
    max_heap = [heights[n-1]]
    is_highest_right = [(heights[n-1], 0), (heights[n-2], 0), (heights[n-3], 0)]
    for i in range(n-1, -1, -1):
        if heights[i] > max_heap[0][0]:
            max_heap = deque([heights[i]])
        elif heights[i] == max_heap[0][0]:
            if queue[0] is queue[1]:
                queue.pop()
            i_max = max_heap[0]
            if i > i_max[1] + k and i >= is_highest_right[0][1] + k:
                queue.append(i_max[0])
                is_highest_right.pop(0)
                max_heap = deque([heights[i]])
            else:
                max_heap = deque([heights[i]])
        else:
            new_chunk = is_highest_right[i-k+1][0] if i-k+1 >= 0 else 0
            if i >= new_chunk + k:
                queue.append(i)
                is_highest_right.append((heights[i], new_chunk))
                max_heap.append(heights[i])
            else:
                max_heap = deque([heights[i]])
                queue.append(i)

    if sum(queue) <= k or max(queue) > max_heap:
        return 'YES'
    else:
        return 'NO'

