                    visiting.add((cost-stop, to))
            for to, c in land[v][::-1]:
                if 2 * c >= cost and (cost - c, cost) not in visiting:
                    queue.append((2 * c, to))
                    visiting.add((cost - c, to))
    return 0


def calculate_difficulty(land, pellets, goals):
