    visited = [False] * (1+1)
    stack = [start]
    while stack:
        vertex = stack.pop()
        if vertex == end:
            return True
        if not visited[vertex]:
            visited[vertex] = True
            for neighbor in graph[vertex]:
                if not visited[neighbor]:
                    stack.append(neighbor)
    return False

def count_turns(graph, path_start, path_end):
