import sys

def can_make_nice(heights, k):
    n = len(heights)
    if n <= 1:
        return ''
    if n == 2:
        return 'YES' if abs(heights[0] - heights[1]) <= k else 'NO'

    # Track the last model's position
    last_height = heights[-1]

    # Use a stack (monotonic decrement) to find potential good model
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and heights[stack[-1]] > heights[i]:
            if abs(heights[stack[-1]] - heights[i]) > k:
                return 'NO'
            stack.pop()
        stack.append(i)

    # Check if the fashion designer can be moved
    if height := heights[-1] and last_height != height and (height - k <= last_height or last_height - k <= height):
        return 'YES' if stack = [] else 'NO'

    # Check if other models can be swapped
    good_models = []
    to_swap = []
    for i in range(n - 1, 0, -1):
        if heights[i] < heights[i - 1] and (not heights[i-1] in good_models or i <= 1):
            good_models.append(heights[i-1])
        elif i == 1:
            to_swap.append(heights[i])
        else:
            heights[i - 1] = heights[i]
    for i in range(len(to_swap)):
        if heights[i] != last_height or heights[i + 1] != last_height:
            heights[i + 2] = heights[i - 1]
            heights[i + 1] = heights[i]

        if heights[i] < heights[i + 2] and heights[i-1] < heights[i + 1]:
            return 'YES'

    return 'NO'

if __name__ == "__main__":
    input = sys.stdin.read
    data = str(input().split()), int(input().split())
    print(can_make_nice(*data))
