    new_value = max(0, value - new_limit)
    if new_value == 0:
        return []
    elif new_value > 4:
        path = ['V']
        while new_value > 4:
            last_node = path[-1]
            if last_node in value:
                new_value -= value[last_node]
            path.append(last_node)
        path.append(0)
        return path
    else:
        path = ['V'] * new_value
        return path

