def is_regular_bracket_sequence(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def rearrange_brackets(brackets):
    n = len(brackets)
    total_length = sum(len(seq) for seq in brackets) * 2
    dp = [1] * (total_length + 1)
    prefix = []

    for seq in brackets:
        for length in range(len(seq), 0, -1):
            for start in range(len(seq) - length + 1):
                if is_regular_bracket_sequence(seq[start:start+length]):
                    prefix_length = start + length
                    for i in range(start, start + length):
                        dp[prefix_length] = max(dp[prefix_length], dp[prefix_length - start + i] + 1)
                    dp[prefix_length] = dp[prefix_length - start + start]

    return dp[total_length]

def main():
    n = int(input())
    brackets = []

    for _ in range(n):
        seq = input().strip()
        brackets.append(seq)

    result = rearrange_brackets(brackets)
    print(result)

if __name__ == "__main__":
    main()
